          @click="searchQuery = ''"
        >
          ✕
        </button>
      </div>

      <!-- Package Manager Selector -->
      <div class="registry-pm-selector">
        <span class="registry-pm-selector__label">CLI:</span>
        <div class="registry-pm-buttons" role="group" aria-label="Package Manager">
          <button
