            :class="{ '-active': selectedPm === 'npx' }"
            @click="selectedPm = 'npx'"
          >
            npx
          </button>
          <button
            type="button"
            class="registry-pm-btn"
            :class="{ '-active': selectedPm === 'pnpm' }"
            @click="selectedPm = 'pnpm'"
          >
            pnpm
          </button>
          <button
            type="button"
            class="registry-pm-btn"
            :class="{ '-active': selectedPm === 'bun' }"
            @click="selectedPm = 'bun'"
          >
            bun
          </button>
        </div>
      </div>
    </div>

    <!-- Category Tabs -->
    <div class="registry-tabs" role="tablist">
      <button
        type="button"
