        @click="activeTab = 'hook'"
      >
        Hooks <span class="registry-tab__count">({{ counts.hook }})</span>
      </button>
    </div>

    <!-- Items Grid -->
    <div v-if="filteredItems.length > 0" class="registry-grid">
      <div
        v-for="item in filteredItems"
        :key="item.name"
        class="registry-card"
        :class="[`registry-card--${item.type.replace(/^registry:/, '')}`]"
      >
        <div class="registry-card__header">
          <div class="registry-card__title-group">
            <h3 class="registry-card__title">
              {{ item.title || item.name }}
            </h3>
            <span class="registry-card__badge" :data-type="item.type">
              {{ typeBadgeLabel(item.type) }}
            </span>
          </div>
          <a
            :href="`/r/${item.name}.json`"
            target="_blank"
            rel="noopener noreferrer"
            class="registry-card__json-btn"
            title="View JSON manifest"
          >
            JSON ↗
          </a>
        </div>

        <p class="registry-card__desc">
          {{ item.description }}
        </p>

        <!-- Dependencies -->
        <div v-if="item.dependencies && item.dependencies.length > 0" class="registry-card__deps">
          <span class="registry-card__deps-label">Deps:</span>
          <span v-for="dep in item.dependencies" :key="dep" class="registry-card__dep-pill">
            {{ dep }}
          </span>
        </div>

        <!-- Command Bar -->
        <div class="registry-card__command">
          <code class="registry-card__command-text">{{ getCommand(item.name) }}</code>
          <button
            type="button"
            class="registry-card__copy-btn"
            :class="{ '-copied': copiedItem === item.name }"
            @click="copyCommand(item.name)"
          >
            {{ copiedItem === item.name ? "Copied!" : "Copy" }}
          </button>
        </div>

        <!-- Expandable Details Toggle -->
        <div v-if="item.files || item.cssVars" class="registry-card__details-wrapper">
          <button
